`},"infinite-loop":{id:"infinite-loop",description:"Runaway loop terminated by execute budget",expectCompileOk:!0,expectExecuteOk:!1,source:`
function edgeScript() {
  return {
    name: "Loop",
    pane: "sub",
    inputs: {},
    calculate() {
      while (true) {}
      return { x: [] };
    },
    plots: { x: { kind: "line", title: "X", color: "#fff" } },
  };
}
edgeScript();
`},"allocation-pressure":{id:"allocation-pressure",description:"Large allocation rejected by output validation",expectCompileOk:!0,expectExecuteOk:!1,source:`
